# REDACTED DERIVATIVE, generated by paper/make_release_tree.py.
# The private canonical file is NOT released and was NOT modified.
# Speaker names are pseudonymised; private roots are masked to
# <PRIVATE_SOURCE_ROOT> etc. Set them locally to re-run.
# Source sha256: 6515e48c19f2ca22c863f4a32ae3339b314260185adb6fd682694653819260e9
"""GATE 4 — THE CORPUS PRODUCER. Deterministic, single source of truth.

⭐ B9. The selection evidence previously lived in orphaned `_gate4_*.json`
dry-run files that NO SCRIPT IN THE REPO PRODUCED. §3.4 requires "the exact
selection-rule execution log", and `GATE4_CORPUS.json` did not exist. This
script is that producer. Everything downstream reads its output; nothing reads a
dry-run file.

⛔ SOURCE IS `<PRIVATE_SOURCE_ROOT>`, BY OWNER DECISION. This script never
looks anywhere else. No other tree is opened, compared, or inferred from.

Run:
    python gate4_corpus.py            # full, with per-file sha256
    python gate4_corpus.py --no-hash  # iteration only; NOT admissible output
"""

import glob
import hashlib
import json
import os
import sys
import time

import numpy as np
import soundfile as sf

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = r"<PRIVATE_SOURCE_ROOT>"
OUT = os.path.join(HERE, "GATE4_CORPUS.json")

SPK = [("Female", "Speaker_01"), ("Female", "Speaker_02"), ("Female", "Speaker_04"),
       ("Female", "Speaker_05"), ("Female", "Speaker_07"), ("Male", "Speaker_03"),
       ("Male", "Speaker_06")]
STATES = ["Neutral", "Angry", "Happy", "Scared", "Shouting", "Whisper"]
LONG_STATES = ["Neutral", "Whisper"]
LANG = "English"

# ---- the frozen selection rule -------------------------------------------
SHORT_MAX_INDEX = 1344
SEL_MIN_S, SEL_MAX_S = 3.0, 10.0          # on NEUTRAL, applied to all states
CALIB_MIN_S, CALIB_MAX_S = 2.0, 3.0       # ⭐ M7: HELD OUT of Set S by construction
N_CALIB_INDICES = 3

#: ⭐ B3. The top duration rung is DERIVED, never asserted. The largest candidate
#: for which EVERY Set L recording qualifies is chosen, so the crossed design is
#: preserved at 100% and no speaker is under-represented.
RUNG_CANDIDATES = (10.0, 12.0, 14.0, 16.0, 18.0, 20.0, 25.0, 30.0)
LADDER_BELOW = (1.0, 2.0, 5.0, 10.0)
LADDER_INDICES = 4                        # monologues carrying the sub-rungs


def sha256(path, buf=1 << 20):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            b = f.read(buf)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def scan(do_hash):
    """Every English file in the declared source. Headers only unless hashing."""
    rows = {}
    t0 = time.time()
    for sex, spk in SPK:
        for st in STATES:
            d = os.path.join(SRC, sex, spk, LANG, st)
            if not os.path.isdir(d):
                raise SystemExit(f"missing folder: {d}")
            for f in sorted(glob.glob(os.path.join(d, "*.wav"))):
                b = os.path.basename(f)
                try:
                    i = int(b.split("_", 1)[0])
                except ValueError:
                    continue
                info = sf.info(f)
                # D16. Two files sharing an index prefix would SILENTLY overwrite
                # one another in this dict. No collision exists today - all 1 638
                # sha256 are distinct - but a silent overwrite is exactly the
                # class of defect this estate refuses to leave latent.
                if (spk, st, i) in rows:
                    raise SystemExit(
                        "INDEX COLLISION: %s / %s / %04d is claimed by both %r "
                        "and %r. The corpus cannot be built while an index is "
                        "ambiguous." % (spk, st, i, rows[(spk, st, i)]["file"], b))
                rows[(spk, st, i)] = {
                    "speaker": spk, "sex": sex[0], "state": st, "index": i,
                    "lang": LANG, "path": f, "file": b,
                    "duration_s": float(info.duration), "sr": int(info.samplerate),
                    "subtype": info.subtype, "channels": int(info.channels),
                    "frames": int(info.frames),
                }
        print(f"  scanned {spk} ({time.time() - t0:.0f}s)")
    return rows


def main():
    do_hash = "--no-hash" not in sys.argv
    print(f"source: {SRC}")
    print(f"hashing: {do_hash}")
    rows = scan(do_hash)
    names = {s for _, s in SPK}
    print(f"\nscanned {len(rows)} files")

    fmts = sorted({(r["sr"], r["subtype"], r["channels"]) for r in rows.values()})
    print(f"distinct formats: {fmts}")

    # ---- absences, recorded not skipped
    absent = []
    for spk in sorted(names):
        for st in STATES:
            have = {i for (s, t, i) in rows if s == spk and t == st}
            for i in range(1, SHORT_MAX_INDEX + 1):
                if i not in have:
                    absent.append({"speaker": spk, "state": st, "index": i,
                                   "state_label": "EXCLUDED - ABSENT"})
    print(f"absent short-phrase files: {len(absent)}")

    # ---- SET S: predicate on NEUTRAL, applied identically to all six states
    neu = {}
    for (s, st, i), r in rows.items():
        if st == "Neutral" and i <= SHORT_MAX_INDEX:
            neu.setdefault(i, {})[s] = r["duration_s"]
    qual = [i for i in sorted(neu)
            if set(neu[i]) == names
            and all(SEL_MIN_S <= d <= SEL_MAX_S for d in neu[i].values())]
    setS, notcrossed = [], {}
    for i in qual:
        miss = [(s, st) for s in sorted(names) for st in STATES
                if (s, st, i) not in rows]
        (notcrossed.setdefault(i, miss) if miss else setS.append(i))
    print(f"\nSET S: {len(qual)} qualify on duration, {len(setS)} fully crossed")

    # ---- ⭐ M7: CALIBRATION SUBSET, HELD OUT OF SET S BY CONSTRUCTION
    calib_pool = [i for i in sorted(neu)
                  if set(neu[i]) == names
                  and all(CALIB_MIN_S <= d < CALIB_MAX_S for d in neu[i].values())
                  and i not in setS]
    calib_idx = []
    for i in calib_pool:
        if all((s, st, i) in rows for s in names for st in STATES):
            calib_idx.append(i)
        if len(calib_idx) == N_CALIB_INDICES:
            break
    print(f"CALIBRATION pool {len(calib_pool)} -> using {calib_idx} "
          f"(disjoint from Set S: {not set(calib_idx) & set(setS)})")

    # ---- SET L: monologues crossed over the long states
    mono = sorted({i for (s, st, i) in rows if i > SHORT_MAX_INDEX})
    setL, mono_notcrossed = [], {}
    for i in mono:
        miss = [(s, st) for s in sorted(names) for st in LONG_STATES
                if (s, st, i) not in rows]
        (mono_notcrossed.setdefault(i, miss) if miss else setL.append(i))
    print(f"SET L: {len(mono)} monologues, {len(setL)} crossed over {LONG_STATES}")

    # ---- ⭐ B3: DERIVE the rung. Never assert it.
    Ldur = [rows[(s, st, i)]["duration_s"]
            for s in sorted(names) for st in LONG_STATES for i in setL]
    rung, coverage = None, {}
    for R in RUNG_CANDIDATES:
        n_ok = sum(1 for d in Ldur if d >= R)
        coverage[R] = {"n_ok": n_ok, "n_total": len(Ldur),
                       "fraction": n_ok / max(len(Ldur), 1)}
        if n_ok == len(Ldur):
            rung = R
    print(f"\nSET L durations: n={len(Ldur)} min={min(Ldur):.2f} max={max(Ldur):.2f}")
    for R in RUNG_CANDIDATES:
        c = coverage[R]
        print(f"   rung {R:>5.1f}s -> {c['n_ok']:>3}/{c['n_total']} "
              f"({100 * c['fraction']:.1f}%)" + ("   <= CHOSEN" if R == rung else ""))
    if rung is None:
        raise SystemExit("no candidate rung keeps every Set L recording - STOP")
    per_spk = {s: sum(1 for st in LONG_STATES for i in setL
                      if rows[(s, st, i)]["duration_s"] >= rung) for s in sorted(names)}
    print(f"   at {rung:g}s, per speaker: {per_spk}  (each of "
          f"{len(LONG_STATES) * len(setL)})")

    ladder = [x for x in LADDER_BELOW if x < rung] + [rung]
    ladder_idx = setL[:LADDER_INDICES]
    print(f"   ladder: {ladder}  on monologues {ladder_idx}")

    # ---- materialise, with hashes
    def cell(spk, st, i):
        r = dict(rows[(spk, st, i)])
        if do_hash:
            r["sha256"] = sha256(r["path"])
        return r

    print("\nmaterialising cells" + (" + sha256" if do_hash else ""))
    S_cells = [cell(s, st, i) for s in sorted(names) for st in STATES for i in setS]
    L_cells = [cell(s, st, i) for s in sorted(names) for st in LONG_STATES for i in setL]
    C_cells = [cell(s, st, i) for s in sorted(names) for st in STATES for i in calib_idx]

    n_ladder_cells = len(sorted(names)) * len(LONG_STATES) * len(ladder_idx) * \
        (len(ladder) - 1)
    doc = {
        "generated_by": "gate4_corpus.py",
        "generated_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "source": SRC,
        "source_decision": "OWNER DECISION 2026-09-12. D: is the Gate 4 source. "
                           "No other tree is read by this script.",
        "hashed": do_hash,
        "formats_observed": [{"sr": a, "subtype": b, "channels": c} for a, b, c in fmts],
        "selection_rule": {
            "short_predicate": f"index<= {SHORT_MAX_INDEX}; ALL 7 speakers' NEUTRAL "
                               f"duration in [{SEL_MIN_S},{SEL_MAX_S}] s; predicate "
                               f"on NEUTRAL only, applied identically to all "
                               f"{len(STATES)} states to preserve the parallel design",
            "short_selection": "ALL qualifying indices are taken - no selection "
                               "step, no free parameter",
            "crossing": "an index is kept only if every speaker x state cell exists; "
                        "a partial index is dropped WHOLE",
            "long_predicate": f"index> {SHORT_MAX_INDEX}; crossed over {LONG_STATES}",
            "rung_derivation": "the LARGEST candidate rung for which EVERY Set L "
                               "recording qualifies, so crossing stays at 100%",
            "rung_candidates_s": list(RUNG_CANDIDATES),
            "calibration": f"⭐ held out of Set S BY CONSTRUCTION: NEUTRAL duration "
                           f"in [{CALIB_MIN_S},{CALIB_MAX_S}) s, which the Set S "
                           f"predicate excludes; first {N_CALIB_INDICES} fully "
                           f"crossed indices",
        },
        "set_S": {"indices": setS, "n_indices": len(setS),
                  "n_recordings": len(S_cells), "states": STATES,
                  "not_crossed": {str(k): v for k, v in notcrossed.items()}},
        "set_L": {"indices": setL, "n_indices": len(setL),
                  "n_recordings": len(L_cells), "states": LONG_STATES,
                  "not_crossed": {str(k): v for k, v in mono_notcrossed.items()},
                  "top_rung_s": rung, "rung_coverage": {str(k): v for k, v
                                                        in coverage.items()},
                  "duration_ladder_s": ladder,
                  "ladder_indices": ladder_idx,
                  "n_ladder_cells": n_ladder_cells},
        "calibration": {"indices": calib_idx, "n_recordings": len(C_cells),
                        "states": STATES,
                        "disjoint_from_set_S": not (set(calib_idx) & set(setS)),
                        "disjoint_from_set_L": not (set(calib_idx) & set(setL))},
        "counts": {
            "distinct_recordings": len(S_cells) + len(L_cells),
            "measurement_cells": len(S_cells) + len(L_cells) + n_ladder_cells,
            "note": "⛔ CELLS ARE NOT RECORDINGS. Ladder cells are REPEATED "
                    "MEASURES on Set L recordings already counted. The "
                    "statistical unit is the RECORDING (see GATE4_PREREG.md §12).",
        },
        "absent_files": absent,
        "cells": {"set_S": S_cells, "set_L": L_cells, "calibration": C_cells},
    }
    for c in doc["cells"].values():
        for r in c:
            r.pop("path", None)
    with open(OUT, "w") as f:
        json.dump(doc, f, indent=1)

    print(f"\nSET S      {len(setS)} indices -> {len(S_cells)} recordings")
    print(f"SET L      {len(setL)} indices -> {len(L_cells)} recordings, "
          f"top rung {rung:g}s")
    print(f"LADDER     {n_ladder_cells} additional cells (repeated measures)")
    print(f"CALIB      {len(calib_idx)} indices -> {len(C_cells)} recordings (HELD OUT)")
    print(f"TOTAL      {doc['counts']['distinct_recordings']} distinct recordings, "
          f"{doc['counts']['measurement_cells']} cells")
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
